{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In CD-1 mice, compound 22a crossed the BBB after systemic administration with a plasma-to-brain ratio of approximately 2:1, directly supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "PET/MRI imaging in a baboon demonstrated rapid and high brain uptake of [11C]8 with peak whole-brain uptake greater than 2.9 SUV, confirming robust systemic BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In rats, orally administered CDA54 showed 33-fold lower brain concentrations than plasma concentrations, indicating poor CNS access for that molecule and providing a contradictory example.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Most direct in-vivo systemic CNS-exposure records support meaningful BBB penetration, including plasma-to-brain ratios, PET brain uptake, brain/CSF detection, and receptor occupancy. The single poor-oral-brain record is outweighed by the consistent positive evidence.",
  "evidence_gaps": [
    "One record (C11) shows poor brain penetration for a different molecule, but it is outweighed by multiple direct positive systemic CNS-access records.",
    "One record (C09) notes an efflux-substrate label, though its CSF-to-unbound-plasma ratio of 0.45 still indicates some CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

